    let messages = [];

    payload.forEach(sensor => {
        let sensorMsg = {
            topic: msg.topic,
            payload: {
                fields: {
                    value: sensor.value,
                    temperature: sensor.name === 'temperature' ? sensor.value : null,
                    humidity: sensor.name === 'humidity' ? sensor.value : null,
