                    voltage: sensor.name === 'voltage' ? sensor.value : null
                },
                tags: {
                    gateway: network,
                    node: nodeName,
                    channel: sensor.channel,
                    type: sensor.type,
                    name: sensor.name,
                    timestamp: new Date()
                },
            }
        };
        messages.push(sensorMsg);
    });

    return [messages];
} else {
    // Handle single object (backward compatibility)
    msg.payload = {
        measurement: 'sensor_data',
        fields: payload,
        tags: {
            gateway: network,
            node: nodeName
        },
        timestamp: new Date()
    };
    return msg;
}

