// Input (msg.payload): [
//   {"channel":1,"type":2,"name":"analog_in","value":56},
//   {"channel":2,"type":103,"name":"temperature","value":25.29999924},
//   ...
// ]
// Output (msg.payload): [{
//   measurement: "sensor",
//   fields: { temperature: 25.29999924, humidity: 60.5, ... }
// }]
let topicParts = msg.topic.split('/'); 
let gateway = topicParts[0]; 
let nodeName = topicParts[1];

function coerceNumber(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : v; // keep as-is if not numeric
}

const arr = Array.isArray(msg.payload) ? msg.payload : [];
if (!arr.length) return null;

const fields = {};
const used = new Set();

for (const it of arr) {
    if (!it || it.name == null) continue;
    let key = String(it.name);

    // De-duplicate field names
    if (used.has(key)) {
        if (it.channel != null) key = `${key}_${it.channel}`;
        let i = 2;
        while (used.has(key)) {
            key = `${it.name}_${i++}`;
        }
    }
    used.add(key);

    fields[key] = coerceNumber(it.value);
}

// Nothing to write?
if (Object.keys(fields).length === 0) return null;

let tags = {
    node: nodeName,
    gateway: gateway,
 //   timestamp: Date.now()
};

// let measurement = { measurement: nodeName };

// Create final format
msg.payload = [fields,tags];
return msg

