// Reads command from msg.payload (string)
// Reads gateway IP from flow.gatewayIP (set by Set gateway IP inject)
// You can also set msg.nodeName or msg.nodeId before calling this node.

var cmd = msg.payload || "";
var gw = flow.get('gatewayIP') || "<gateway-ip>"; // fallback placeholder

switch(cmd) {
    case 'gw_info':
        msg.url = `http://${gw}/api/gw/info`;
        msg.method = 'GET';
        break;
    case 'list_nodes':
        msg.url = `http://${gw}/api/gw/nodes`;
        msg.method = 'GET';
        break;
    case 'node_info':
        // try msg.nodeName, otherwise default to 'MyNode'
        var nodeName = msg.nodeName || 'MyNode';
        msg.url = `http://${gw}/api/node/node?nodename=${encodeURIComponent(nodeName)}`;
        msg.method = 'GET';
        break;
    case 'restart_node':
        var nodeName = msg.nodeName || 'MyNode';
        msg.url = `http://${gw}/api/node/restart?nodename=${encodeURIComponent(nodeName)}`;
        msg.method = 'PUT';
        break;
    case 'delete_node':
        // can use nodeid or nodename; here using nodeid
        var nodeId = msg.nodeId || '5';
        msg.url = `http://${gw}/api/node/node?nodeid=${encodeURIComponent(nodeId)}`;
        msg.method = 'DELETE';
        break;
    case 'restart_gw':
        msg.url = `http://${gw}/api/gw/restart?confirm=1`;
        msg.method = 'PUT';
        break;
    default:
        node.warn('Unknown command: ' + cmd);
        msg = {payload: {error: 'unknown command'}};
        return [null];
}

// Ensure HTTP Request node uses msg.method and msg.url
return msg;

// msg.payload is the parsed JSON response (because HTTP node returns obj)
